    if "entry_price" not in state:
        state["entry_price"] = 0.0

    current_bar = len(hist) - 1
    close = hist.close[-1]
    atr = ind.atr(hist, 14)[-1]

    # Donchian lookback
    lookback = 96

    # Get prior 96-bar high and low (excluding current bar)
    if len(hist) > lookback:
        prior_high = ind.highest(hist.high[:-1], lookback)[-1]
        prior_low = ind.lowest(hist.low[:-1], lookback)[-1]
    else:
        prior_high = np.nan
        prior_low = np.nan

    # Check for bearish Donchian signal (close below prior 96-bar low)
    bearish_signal = False
    if not np.isnan(prior_low) and close < prior_low:
        bearish_signal = True

    # If we have an open position and bearish signal, exit at next open
    if pos != 0.0 and bearish_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # Check for time stop (32 bars after entry)
    if pos != 0.0:
        bars_held = current_bar - state["entry_bar"]
        if bars_held >= 32:
            return {"target": 0.0, "stop": None, "take": None}

    # Check for bullish Donchian signal (close above prior 96-bar high)
    bullish_signal = False
    if not np.isnan(prior_high) and close > prior_high:
        bullish_signal = True

    # Entry logic: only if flat
    if pos == 0.0 and bullish_signal:
        # Size: risk 1% of equity per 1 ATR
        # position_fraction = 0.01 * close / (1 * atr)
        if atr > 0:
            target = 0.01 * close / atr
        else:
            target = 0.05

        # Cap at 1.0, floor at 0.05
        target = max(0.05, min(1.0, target))

        # Round to 0.05 grid
        target = round(target / 0.05) * 0.05

        # Record entry details
        state["entry_bar"] = current_bar
        state["entry_atr"] = atr
        state["entry_price"] = close

        return {"target": target, "stop": None, "take": None}

    # If we're in a position, maintain it with time stop
    if pos != 0.0:
        bars_held = current_bar - state["entry_bar"]

        # Time stop at 32 bars
        if bars_held >= 32:
            return {"target": 0.0, "stop": None, "take": None}

        # Otherwise hold position, no stop/take
        return {"target": pos, "stop": None, "take": None}

    # No signal, stay flat
    return {"target": 0.0, "stop": None, "take": None}

