    # Initialize state
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "entry_bar" not in state:
        state["entry_bar"] = 0
    if "trade_direction" not in state:
        state["trade_direction"] = 0  # 0=flat, 1=long, -1=short

    current_bar = len(hist) - 1

    # Check if we need to exit due to time stop (32 bars)
    if state["trade_direction"] != 0:
        bars_held = current_bar - state["entry_bar"]
        if bars_held >= 32:
            return {"target": 0.0, "stop": None, "take": None}

    # Calculate box from prior 16 bars (bars -17 to -2, i.e., indices -17 to -2)
    if len(hist) >= 18:
        box_high = ind.highest(hist.high[-17:-1], 16)[-1]
        box_low = ind.lowest(hist.low[-17:-1], 16)[-1]
        box_height = box_high - box_low

        # Only trade if box height <= 3 ATR
        if box_height <= 3 * atr_val:
            # Check for breakout signals when flat
            if pos == 0.0:
                # Long signal: close above box top
                if close > box_high:
                    state["entry_price"] = close
                    state["entry_atr"] = atr_val
                    state["entry_bar"] = current_bar
                    state["trade_direction"] = 1
                    target = 0.25
                    stop = close - atr_val
                    take = None
                    return {"target": target, "stop": stop, "take": take}

                # Short signal: close below box bottom
                elif close < box_low:
                    state["entry_price"] = close
                    state["entry_atr"] = atr_val
                    state["entry_bar"] = current_bar
                    state["trade_direction"] = -1
                    target = -0.25
                    stop = close + atr_val
                    take = None
                    return {"target": target, "stop": stop, "take": take}

            # Check for opposite signal while in a trade
            elif state["trade_direction"] == 1 and close < box_low:
                # Long trade, short signal: exit
                state["trade_direction"] = 0
                return {"target": 0.0, "stop": None, "take": None}

            elif state["trade_direction"] == -1 and close > box_high:
                # Short trade, long signal: exit
                state["trade_direction"] = 0
                return {"target": 0.0, "stop": None, "take": None}

    # Maintain current position with stops
    if pos != 0.0:
        if pos > 0:
            stop = state["entry_price"] - state["entry_atr"]
            return {"target": pos, "stop": stop, "take": None}
        else:
            stop = state["entry_price"] + state["entry_atr"]
            return {"target": pos, "stop": stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

