    if "entry_price" not in state:
        state["entry_price"] = None
    if "entry_bar" not in state:
        state["entry_bar"] = None
    if "partial_taken" not in state:
        state["partial_taken"] = False

    current_bar = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    # Compute 96-bar Donchian channel on 15m
    donchian_high = ind.highest(hist.high, 96)[-1]
    donchian_low = ind.lowest(hist.low, 96)[-1]

    # Get 4h trend filter: last completed 4h close vs 50 EMA
    htf_4h = hist.htf(240)
    if len(htf_4h.close) > 0:
        ema_50_4h = ind.ema(htf_4h.close, 50)[-1]
        last_4h_close = htf_4h.close[-1]
        trend_ok = last_4h_close > ema_50_4h
    else:
        trend_ok = False

    # Get ATR for sizing and profit target
    atr = ind.atr(hist, 14)[-1]

    # Check for breakout: close outside the 96-bar Donchian
    prev_close = hist.close[-2] if len(hist) > 1 else close

    breakout_high = False
    breakout_low = False

    if close > donchian_high:
        breakout_high = True
    if close < donchian_low:
        breakout_low = True

    # Arm logic: when a breakout occurs, arm that extreme level for 32 bars
    if breakout_high:
        state["armed_level"] = donchian_high
        state["armed_bar"] = current_bar
    elif breakout_low:
        # Short signal: if we're long, close the position
        if pos > 0:
            return {"target": 0.0, "stop": None, "take": None}

    # Check if armed level has expired (32 bars)
    if state["armed_level"] is not None and state["armed_bar"] is not None:
        bars_since_armed = current_bar - state["armed_bar"]
        if bars_since_armed >= 32:
            state["armed_level"] = None
            state["armed_bar"] = None

    # Entry logic: wick touches armed level and trend filter agrees
    entry_signal = False
    if state["armed_level"] is not None and trend_ok and pos == 0.0:
        # Check if wick touched the armed level
        if low <= state["armed_level"] <= high:
            entry_signal = True

    # Execute entry
    if entry_signal:
        # Volatility sizing: risk 0.25% per 1 ATR
        target_pos = 0.0025 * close / (1.0 * atr)
        target_pos = max(0.05, min(1.0, target_pos))
        target_pos = round(target_pos / 0.05) * 0.05

        state["entry_atr"] = atr
        state["entry_price"] = close
        state["entry_bar"] = current_bar
        state["partial_taken"] = False

        return {"target": target_pos, "stop": None, "take": None}

    # Manage open position
    if pos > 0.0:
        # Calculate profit in ATR terms
        profit_atr = (close - state["entry_price"]) / state["entry_atr"]

        # Partial profit taking: once 1.5 ATR in profit, cut to half
        if profit_atr >= 1.5 and not state["partial_taken"]:
            state["partial_taken"] = True
            new_target = pos / 2.0
            new_target = round(new_target / 0.05) * 0.05
            return {"target": new_target, "stop": None, "take": None}

        # Time stop: 32 bars from entry
        bars_in_trade = current_bar - state["entry_bar"]
        if bars_in_trade >= 32:
            return {"target": 0.0, "stop": None, "take": None}

        # Set stop and take levels
        stop_level = state["entry_price"] - 1.5 * state["entry_atr"]
        take_level = state["entry_price"] + 3.0 * state["entry_atr"]

        return {"target": pos, "stop": stop_level, "take": take_level}

    return {"target": pos, "stop": None, "take": None}

