def strategy(hist, state, pos, ind) -> dict:
    """
    Long-only Donchian trend system with pyramiding.
    - Entry: close above 192-bar high, 0.5 size
    - Pyramid: +0.5 size when price moves 1 ATR above last add price (max 2 pyramids, total 1.0)
    - Exit: 32-bar time stop from signal bar, or bearish Donchian breakdown (close below 192-bar low)
    """

    # Initialize state keys if needed
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "last_add_price" not in state:
        state["last_add_price"] = 0.0
    if "pyramid_count" not in state:
        state["pyramid_count"] = 0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0

    close = hist.close[-1]
    high_192 = ind.highest(hist.close, 192)[-1]
    low_192 = ind.lowest(hist.close, 192)[-1]
    atr = ind.atr(hist, 14)[-1]

    current_bar = len(hist) - 1

    # Check for bearish Donchian breakdown (exit condition)
    if pos > 0 and close < low_192:
        # Bail out: close position at next open
        return {"target": 0.0, "stop": None, "take": None}

    # Check for 32-bar time stop from signal bar
    if pos > 0 and state["entry_bar"] >= 0:
        bars_held = current_bar - state["entry_bar"]
        if bars_held >= 32:
            # Exit at next open
            return {"target": 0.0, "stop": None, "take": None}

    # Entry signal: close above 192-bar high
    if pos == 0.0 and close > high_192:
        # Fire entry: 0.5 size
        state["entry_bar"] = current_bar
        state["last_add_price"] = close
        state["pyramid_count"] = 0
        state["entry_atr"] = atr
        return {"target": 0.5, "stop": None, "take": None}

    # Pyramiding logic: add 0.5 size when price moves 1 ATR above last add price
    if pos > 0 and state["pyramid_count"] < 2 and pos < 1.0:
        entry_atr = state["entry_atr"]
        if entry_atr > 0:
            pyramid_threshold = state["last_add_price"] + entry_atr
            if close >= pyramid_threshold:
                # Add another 0.5 size
                new_pos = min(pos + 0.5, 1.0)
                state["last_add_price"] = close
                state["pyramid_count"] += 1
                return {"target": new_pos, "stop": None, "take": None}

    # No change
    return {"target": pos, "stop": None, "take": None}

