def strategy(hist, state, pos, ind) -> dict:
    close = hist.close[-1]
    atr_val = ind.atr(hist, 14)[-1]
    rsi = ind.rsi(hist.close, 21)[-1]
    rsi_prev = ind.rsi(hist.close, 21)[-2]

    # Initialize state
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "add_count" not in state:
        state["add_count"] = 0
    if "last_add_price" not in state:
        state["last_add_price"] = 0.0
    if "breakeven_stop" not in state:
        state["breakeven_stop"] = False
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "highest_high" not in state:
        state["highest_high"] = 0.0

    target = pos
    stop = None
    take = None

    # Check for bearish RSI cross below 75 (close out)
    if pos > 0 and rsi_prev >= 75 and rsi < 75:
        target = 0.0
        return {"target": target, "stop": stop, "take": take}

    # Entry: RSI crosses above 25 when flat
    if pos == 0.0 and rsi_prev <= 25 and rsi > 25:
        state["entry_price"] = close
        state["entry_atr"] = atr_val
        state["add_count"] = 0
        state["last_add_price"] = close
        state["breakeven_stop"] = False
        state["entry_bar"] = len(hist) - 1
        state["highest_high"] = hist.high[-1]
        target = 0.25

    # Pyramid logic: add up to 2 times when price is 1 ATR above last add
    elif pos > 0 and state["add_count"] < 2:
        if close >= state["last_add_price"] + state["entry_atr"]:
            state["add_count"] += 1
            state["last_add_price"] = close
            target = pos + 0.25

    # Track highest high for trailing stop
    if pos > 0:
        state["highest_high"] = max(state["highest_high"], hist.high[-1])

    # Check if we're 0.5 ATR in profit to move stop to breakeven
    if pos > 0 and not state["breakeven_stop"]:
        if close >= state["entry_price"] + 0.5 * state["entry_atr"]:
            state["breakeven_stop"] = True

    # Calculate stops and takes
    if pos > 0:
        # Breakeven stop (once activated, stays)
        if state["breakeven_stop"]:
            stop = state["entry_price"]
        else:
            stop = state["entry_price"] - 2.0 * state["entry_atr"]

        # Trailing stop: 4 ATR behind highest high
        trailing_stop = state["highest_high"] - 4.0 * state["entry_atr"]
        if state["breakeven_stop"]:
            stop = max(stop, trailing_stop)
        else:
            stop = max(stop, trailing_stop)

        # Time stop on bar 16
        bars_held = len(hist) - 1 - state["entry_bar"]
        if bars_held >= 16:
            stop = close  # Exit at next open

    return {"target": target, "stop": stop, "take": take}

