    close = hist.close[-1]
    rsi = ind.rsi(hist.close, 7)
    atr = ind.atr(hist, 14)

    current_bar = len(hist) - 1
    bars_in_trade = current_bar - state["entry_bar"]

    # Check if we should exit due to time limit (64 bars)
    if pos != 0.0 and bars_in_trade >= 64:
        return {"target": 0.0, "stop": None, "take": None}

    # Get RSI values for cross detection
    rsi_current = rsi[-1]
    rsi_prev = rsi[-2] if len(rsi) >= 2 else rsi_current

    # Detect RSI crosses
    long_signal = False
    short_signal = False

    # Long signal: RSI crosses above 20 (was at or below 20, now above 20)
    if rsi_prev <= 20 and rsi_current > 20:
        long_signal = True

    # Short signal: RSI crosses below 80 (was at or above 80, now below 80)
    if rsi_prev >= 80 and rsi_current < 80:
        short_signal = True

    # Handle opposite signal while in trade
    if pos > 0.0 and short_signal:
        return {"target": 0.0, "stop": None, "take": None}

    if pos < 0.0 and long_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # Entry logic when flat
    if pos == 0.0:
        if long_signal:
            # Calculate position size: risk 0.5% per 1 ATR, floor 5%, cap 100%
            atr_current = atr[-1]
            if atr_current > 0:
                target_pos = (0.005 * close) / (1.0 * atr_current)
            else:
                target_pos = 0.05

            # Apply floor and cap
            target_pos = max(0.05, min(1.0, target_pos))

            # Round to 0.05 grid
            target_pos = math.floor(target_pos / 0.05 + 0.5) * 0.05

            # Store entry info
            state["entry_bar"] = current_bar
            state["entry_atr"] = atr_current
            state["entry_price"] = close

            # Calculate stop and take
            stop = close - 2.0 * state["entry_atr"]
            take = close + 2.0 * state["entry_atr"]

            return {"target": target_pos, "stop": stop, "take": take}

        elif short_signal:
            # Calculate position size: risk 0.5% per 1 ATR, floor 5%, cap 100%
            atr_current = atr[-1]
            if atr_current > 0:
                target_pos = (0.005 * close) / (1.0 * atr_current)
            else:
                target_pos = 0.05

            # Apply floor and cap
            target_pos = max(0.05, min(1.0, target_pos))

            # Round to 0.05 grid
            target_pos = math.floor(target_pos / 0.05 + 0.5) * 0.05

            # Store entry info
            state["entry_bar"] = current_bar
            state["entry_atr"] = atr_current
            state["entry_price"] = close

            # Calculate stop and take (inverted for short)
            stop = close + 2.0 * state["entry_atr"]
            take = close - 2.0 * state["entry_atr"]

            return {"target": -target_pos, "stop": stop, "take": take}

    # Maintain position with stops and takes
    if pos > 0.0:
        stop = state["entry_price"] - 2.0 * state["entry_atr"]
        take = state["entry_price"] + 2.0 * state["entry_atr"]
        return {"target": pos, "stop": stop, "take": take}

    elif pos < 0.0:
        stop = state["entry_price"] + 2.0 * state["entry_atr"]
        take = state["entry_price"] - 2.0 * state["entry_atr"]
        return {"target": pos, "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

