    bearish_signal = False
    if current_bar >= 20:
        prior_20_low = ind.lowest(hist.low, 20)[-1]
        if close < prior_20_low:
            bearish_signal = True

    # If in trade and bearish signal, exit
    if state["in_trade"] and bearish_signal:
        state["in_trade"] = False
        state["armed"] = False
        return {"target": 0.0, "stop": None, "take": None}

    # Time-based exit: 64 bars since signal
    if state["in_trade"]:
        bars_since_signal = current_bar - state["signal_bar"]
        if bars_since_signal >= 64:
            state["in_trade"] = False
            state["armed"] = False
            return {"target": 0.0, "stop": None, "take": None}

    # Arm the setup: look for 48-bar high or low
    if not state["armed"] and not state["in_trade"]:
        if current_bar >= 48:
            prior_48_high = ind.highest(hist.high, 48)[-2]  # exclude current bar
            prior_48_low = ind.lowest(hist.low, 48)[-2]     # exclude current bar

            # Check if we have a new high or low in the last 48 bars (before current)
            if current_bar >= 48:
                recent_high = ind.highest(hist.high, 49)[-2]  # 49 bars to get prior 48
                recent_low = ind.lowest(hist.low, 49)[-2]

                # Arm if close breaks above prior 48-bar high or below prior 48-bar low
                if close > prior_48_high or close < prior_48_low:
                    state["armed"] = True
                    if close > prior_48_high:
                        state["breakout_level"] = prior_48_high
                    else:
                        state["breakout_level"] = prior_48_low
                    state["signal_bar"] = current_bar

    # Check if armed setup is still valid (within 64 bars)
    if state["armed"] and not state["in_trade"]:
        bars_since_arm = current_bar - state["signal_bar"]
        if bars_since_arm >= 64:
            state["armed"] = False

    # Entry: retest of breakout level (wick touches or crosses)
    if state["armed"] and not state["in_trade"] and pos == 0.0:
        # For long: breakout level is a high, retest means low touches or goes below
        if state["breakout_level"] > 0:
            if low <= state["breakout_level"]:
                # Entry at half size
                target_pos = 0.5
                state["in_trade"] = True
                state["entry_price"] = close
                state["entry_atr"] = atr_val

                # Stop loss: initially none, will be set to breakeven once 0.5 ATR in profit
                stop_loss = None
                take_profit = state["entry_price"] + 4 * state["entry_atr"]

                return {"target": target_pos, "stop": stop_loss, "take": take_profit}

    # Manage active trade
    if state["in_trade"] and pos > 0.0:
        profit = close - state["entry_price"]

        # Stop loss: move to breakeven once 0.5 ATR in profit
        stop_loss = None
        if profit >= 0.5 * state["entry_atr"]:
            stop_loss = state["entry_price"]

        # Take profit: 4 ATR
        take_profit = state["entry_price"] + 4 * state["entry_atr"]

        return {"target": pos, "stop": stop_loss, "take": take_profit}

    return {"target": pos, "stop": None, "take": None}

