            state["entry_atr"] = atr

        # While armed, check for retest entry
        if state["armed"]:
            # Update breakout level if we get a newer breakout
            if close > state["breakout_level"]:
                state["breakout_level"] = close
                state["armed_bar"] = current_bar

            # Check if armed for more than 16 bars
            bars_armed = current_bar - state["armed_bar"]
            if bars_armed > 16:
