                state["scaled_out"] = False
                state["cooldown_until"] = current_bar + 96
                return {"target": 0.75, "stop": None, "take": None}

    # If in a long position, manage exits
    if pos > 0.0:
        profit_level = state["entry_price"] + 3.0 * state["entry_atr"]

        # Scale out half size on first close at or over 3 ATR profit
        if not state["scaled_out"] and close >= profit_level:
            state["scaled_out"] = True
            return {"target": pos * 0.5, "stop": None, "take": profit_level}

        # Hard take-profit at 3 ATR
        take = profit_level

        # Stop at entry price (breakeven)
        stop = state["entry_price"]

        return {"target": pos, "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

