def strategy(hist, state, pos, ind) -> dict:
    """
    96-bar breakout with retest entry, scaling, trailing box, and cooldown.
    """

    # Initialize state keys
    if "signal_bar" not in state:
        state["signal_bar"] = -1
    if "signal_type" not in state:
        state["signal_type"] = 0  # 0=none, 1=long, -1=short
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "box_high" not in state:
        state["box_high"] = 0.0
    if "box_low" not in state:
        state["box_low"] = 0.0
    if "scale_count" not in state:
        state["scale_count"] = 0
    if "max_profit_close" not in state:
        state["max_profit_close"] = 0.0
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1
    if "breakout_level" not in state:
        state["breakout_level"] = 0.0
    if "breakout_type" not in state:
        state["breakout_type"] = 0  # 0=none, 1=long, -1=short
    if "retest_armed_until" not in state:
        state["retest_armed_until"] = -1

    current_bar = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    atr = ind.atr(hist, 14)[-1]

    # Check cooldown
    in_cooldown = current_bar < state["cooldown_until"]

    # Detect 96-bar breakout (only when flat and not in cooldown)
    if pos == 0.0 and not in_cooldown:
        if current_bar >= 96:
            prior_96_high = ind.highest(hist.high[:-1], 96)[-1]
            prior_96_low = ind.lowest(hist.low[:-1], 96)[-1]

            # Long breakout: close above prior 96-bar high
            if close > prior_96_high and state["breakout_type"] != 1:
                state["breakout_type"] = 1
                state["breakout_level"] = prior_96_high
                state["retest_armed_until"] = current_bar + 16
                state["signal_bar"] = -1
                state["signal_type"] = 0

            # Short breakout: close below prior 96-bar low
            elif close < prior_96_low and state["breakout_type"] != -1:
                state["breakout_type"] = -1
                state["breakout_level"] = prior_96_low
                state["retest_armed_until"] = current_bar + 16
                state["signal_bar"] = -1
                state["signal_type"] = 0

    # Retest entry logic (within 16 bars of breakout)
    if pos == 0.0 and not in_cooldown and current_bar <= state["retest_armed_until"]:
        if state["breakout_type"] == 1:
            # Long retest: price touches or goes below breakout level
            if low <= state["breakout_level"]:
                state["signal_type"] = 1
                state["signal_bar"] = current_bar
                state["entry_price"] = close
                state["entry_atr"] = atr
                state["box_high"] = close + 2 * atr
                state["box_low"] = close - 2 * atr
                state["scale_count"] = 0
                state["max_profit_close"] = close
                state["breakout_type"] = 0
                state["retest_armed_until"] = -1

        elif state["breakout_type"] == -1:
            # Short retest: price touches or goes above breakout level
            if high >= state["breakout_level"]:
                state["signal_type"] = -1
                state["signal_bar"] = current_bar
                state["entry_price"] = close
                state["entry_atr"] = atr
                state["box_high"] = close + 2 * atr
                state["box_low"] = close - 2 * atr
                state["scale_count"] = 0
                state["max_profit_close"] = close
                state["breakout_type"] = 0
                state["retest_armed_until"] = -1

    # Opposite signal while in trade: close position
    if pos != 0.0:
        if state["signal_type"] == 1 and close < ind.lowest(hist.low[:-1], 96)[-1]:
            # Short signal while long
            return {"target": 0.0, "stop": None, "take": None}
        elif state["signal_type"] == -1 and close > ind.highest(hist.high[:-1], 96)[-1]:
            # Long signal while short
            return {"target": 0.0, "stop": None, "take": None}

    # Time out after 16 bars from signal
    if pos != 0.0 and state["signal_bar"] >= 0:
        bars_since_signal = current_bar - state["signal_bar"]
        if bars_since_signal >= 16:
            return {"target": 0.0, "stop": None, "take": None}

    # Scaling logic
    target = pos
    if pos != 0.0 and state["signal_bar"] >= 0:
        bars_since_signal = current_bar - state["signal_bar"]

        if state["signal_type"] == 1:
            # Long: scale up when price is 1 ATR in profit
            profit_threshold = state["entry_price"] + state["entry_atr"]
            if close >= profit_threshold and state["scale_count"] < 2:
                # Check if we haven't scaled at this level yet
                if close > state["max_profit_close"]:
                    state["max_profit_close"] = close
                    state["scale_count"] += 1
                    # Add 0.5 position (half size)
                    target = min(pos + 0.5, 1.0)

        elif state["signal_type"] == -1:
            # Short: scale up when price is 1 ATR in profit
            profit_threshold = state["entry_price"] - state["entry_atr"]
            if close <= profit_threshold and state["scale_count"] < 2:
                if close < state["max_profit_close"]:
                    state["max_profit_close"] = close
                    state["scale_count"] += 1
                    target = max(pos - 0.5, -1.0)

    # Initial entry: half size
    if state["signal_bar"] == current_bar and pos == 0.0:
        if state["signal_type"] == 1:
            target = 0.5
        elif state["signal_type"] == -1:
            target = -0.5

    # Trailing box and stops/takes
    stop_price = None
    take_price = None

    if pos != 0.0 and state["signal_bar"] >= 0:
        if state["signal_type"] == 1:
            # Long: hard stop 2 ATR below entry, take 2 ATR above entry
            stop_price = state["box_low"]
            take_price = state["box_high"]

            # Ratchet box: if close is 2 ATR deeper in green, move box up
            if close >= state["entry_price"] + 2 * state["entry_atr"]:
                state["box_high"] = close + 2 * state["entry_atr"]
                state["box_low"] = close - 2 * state["entry_atr"]

        elif state["signal_type"] == -1:
            # Short: hard stop 2 ATR above entry, take 2 ATR below entry
            stop_price = state["box_high"]
            take_price = state["box_low"]

            # Ratchet box: if close is 2 ATR deeper in green, move box down
            if close <= state["entry_price"] - 2 * state["entry_atr"]:
                state["box_high"] = close + 2 * state["entry_atr"]
                state["box_low"] = close - 2 * state["entry_atr"]

    # Handle position closure (stop/take triggered or timeout)
    if pos != 0.0 and state["signal_bar"] >= 0:
        bars_since_signal = current_bar - state["signal_bar"]

        # Check if stop or take would trigger on next bar (we set them for next bar)
        # For now, just set them; the engine handles triggering

        if bars_since_signal >= 16:
            # Timeout: close position
            target = 0.0
            state["cooldown_until"] = current_bar + 48
            state["signal_type"] = 0
            state["signal_bar"] = -1

    # Round target to 0.05 grid
    target = round(target * 20) / 20

    return {"target": target, "stop": stop_price, "take": take_price}

