import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    """
    Box breakout strategy on 15-minute bars.
    - 64-bar channel for breakout levels
    - Box height max 6 ATR
    - Risk 1% per 2 ATR, capped at 100%, floored at 5%
    - TP 4 ATR from entry
    """

    close = hist.close[-1]
    atr_val = ind.atr(hist, 14)[-1]

    # Get the 64-bar high and low (prior 64 bars, not including current)
    if len(hist) < 65:
        return {"target": pos, "stop": None, "take": None}

    prior_64_high = ind.highest(hist.high[:-1], 64)[-1]
    prior_64_low = ind.lowest(hist.low[:-1], 64)[-1]

    box_height = prior_64_high - prior_64_low

    # Check if box height exceeds 6 ATR
    if box_height > 6 * atr_val:
        return {"target": pos, "stop": None, "take": None}

    # Determine signals
    long_signal = close > prior_64_high
    short_signal = close < prior_64_low

    # Handle opposite signal when in a trade
    if pos > 0 and short_signal:
        return {"target": 0.0, "stop": None, "take": None}
    if pos < 0 and long_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # Only open when flat
    if pos != 0.0:
        # Maintain existing trade with stops and takes
        if "entry_price" in state and "entry_atr" in state:
            entry_price = state["entry_price"]
            entry_atr = state["entry_atr"]

            if pos > 0:
                stop_level = entry_price - 2 * entry_atr
                take_level = entry_price + 4 * entry_atr
            else:
                stop_level = entry_price + 2 * entry_atr
                take_level = entry_price - 4 * entry_atr

            return {"target": pos, "stop": stop_level, "take": take_level}
        else:
            return {"target": pos, "stop": None, "take": None}

    # Open new trade when flat
    if long_signal:
        # Risk 1% per 2 ATR, capped at 100%, floored at 5%
        target_fraction = (0.01 * close) / (2 * atr_val)
        target_fraction = max(0.05, min(1.0, target_fraction))
        target_fraction = math.floor(target_fraction * 20) / 20  # Round to 0.05 grid

        state["entry_price"] = close
        state["entry_atr"] = atr_val

        stop_level = close - 2 * atr_val
        take_level = close + 4 * atr_val

        return {"target": target_fraction, "stop": stop_level, "take": take_level}

    elif short_signal:
        # Risk 1% per 2 ATR, capped at 100%, floored at 5%
        target_fraction = (0.01 * close) / (2 * atr_val)
        target_fraction = max(0.05, min(1.0, target_fraction))
        target_fraction = math.floor(target_fraction * 20) / 20  # Round to 0.05 grid
        target_fraction = -target_fraction

        state["entry_price"] = close
        state["entry_atr"] = atr_val

        stop_level = close + 2 * atr_val
        take_level = close - 4 * atr_val

        return {"target": target_fraction, "stop": stop_level, "take": take_level}

    return {"target": pos, "stop": None, "take": None}

