    if bar_index > 0:
        prev_time = hist.time[-2]
        prev_day = prev_time // (24 * 60 * 60 * 1000)
        curr_day = current_time // (24 * 60 * 60 * 1000)
        if curr_day > prev_day:
            state["entries_today"] = 0

