    highest_96 = ind.highest(hist.high, 96)[-1]
    if bar_index >= 96:
        prev_highest_96 = ind.highest(hist.high[:-1], 96)[-1] if bar_index > 96 else hist.high[-2]
        if high >= highest_96 and high > prev_highest_96:
            state["breakout_level"] = highest_96
            state["breakout_bar"] = bar_index

