    if state["breakout_level"] > 0 and bar_index - state["breakout_bar"] <= 32:
        # Check for retest (price touches the breakout level)
        if pos == 0 and low <= state["breakout_level"] and state["entries_today"] < 2:
            # Entry signal: go long at quarter size
            target = 0.25
            state["entries_today"] += 1
            state["last_entry_time"] = current_time
            state["entry_atr"] = atr
            state["last_add_price"] = close
            state["pyramid_count"] = 1

